  motions: {
    commandement: {
      council: "gaillard", title: "Le commandement", shown: { seen: "C_assemblee" },
      text: "Guénolé Le Bihan lit la proposition, debout sur le cabestan, en ânonnant un peu : « Que le second, Morvan Le Hir, commande la Sterne jusqu'à Marbecq, puisque le capitaine est hors d'état, et que l'équipage lui obéisse comme au capitaine. »",
      lean: { guenole: "pour", kerlo: "pour", rozenn: "indecis", daoulas: "contre", erwan: "pour" },
      say: {
        guenole: { pour: "Un navire sans maître, c'est un cheval sans bride. Le second connaît son métier.", contre: "Je ne mets pas la Sterne entre les mains d'un homme qui fait percer nos tonneaux." },
        kerlo: { pour: "Je tiens la barre pour qui commande. Autant que ce soit lui.", contre: "La route qu'il me fait tenir depuis trois nuits me plaît pas. Contre." },
        rozenn: { pour: "Qu'il commande, et qu'on en finisse.", contre: "C'est lui qui porte le grog au capitaine, tous les soirs. Contre." },
        daoulas: { contre: "J'ai soigné assez de marins pour savoir que je n'aime pas ce qui arrive au capitaine. Contre.", pour: "Pour. Je me suis peut-être trompé." },
        erwan: { pour: "Pour le second.", contre: "Contre." },
      },
      heroSay: { pour: "Il faut un maître à bord.", contre: "Pas lui.", abstention: "Je réponds de la cargaison, pas du navire." },
      fx: { adopte: { set: { commandement: "morvan" } }, rejete: { set: { commandement: "conseil" } } },
    },
    retour: {
      council: "gaillard", title: "Le retour", shown: { seen: "C_retour" },
      text: "Guénolé lit la seconde proposition, plus lentement que la première : « Que la Sterne vire de bord et rentre à Port-Aubier, pour que la justice du port sache ce qu'on a mis dans sa cale et pourquoi. »",
      lean: { guenole: "indecis", kerlo: "contre", rozenn: "pour", daoulas: "pour", erwan: "contre" },
      say: {
        guenole: { pour: "Je veux voir la tête de l'armateur quand on lui ramènera son navire. Pour.", contre: "Six jours de mer de plus, avec ce qui nous reste d'eau ? Contre." },
        kerlo: { pour: "Pour. Je connais la route du retour.", contre: "Les Îles sont à deux jours. Port-Aubier à huit. Contre." },
        rozenn: { pour: "Pour. Et que le juge goûte ma soupe.", contre: "Contre. On a faim, on a soif, on va au plus près." },
        daoulas: { pour: "Un tribunal ne croit que ce qu'il voit. Ramenons-lui ce qu'il faut voir.", contre: "Le capitaine a besoin d'un vrai médecin, à Marbecq. Contre." },
        erwan: { pour: "Pour.", contre: "Contre." },
      },
      heroSay: { pour: "Que Corbière réponde de sa cale.", contre: "Les Îles d'abord.", abstention: "Je laisse l'équipage choisir." },
      fx: { adopte: { set: { cap_route: "retour" } }, rejete: { set: { cap_route: "marbecq" } } },
    },
  },
