  // ------------------------------------------------------------------ mysteries and clues
  mysteries: {
    M: { title: "Pourquoi la Sterne a-t-elle pris la mer ?", act: "II", solved: "m:verite",
      answer: { person: "morvan", motive: "prime", text: "Pour faire naufrage. Maître Corbière, ruiné, a assuré la Sterne et une cargaison de sable pour trois fois leur valeur ; Morvan Le Hir, payé par lui, devait la perdre sur les Dents de Morgue et fuir en chaloupe, comme il l'avait fait deux ans plus tôt avec la Bergeronnette.",
        proofs: ["m_sable", "m_chaloupe", "m_police", "m_bergeronnette", "m_lettre"] },
      suspects: ["morvan", "guenole", "kerlo", "rozenn", "daoulas", "erwan"],
      motives: {
        commandement: "Pour prendre le commandement à la place du capitaine",
        coffre: "Pour voler le coffre de bord",
        vengeance: "Par vengeance contre le capitaine Coët",
        prime: "Pour l'argent de l'armateur : perdre le navire et faire payer les assureurs",
      },
      accuseTitle: "Devant l'équipage",
      accuseText: {
        qui: "L'équipage s'est rassemblé au pied du grand mât, les bras croisés. Guénolé te fait signe de parler. Qui accuses-tu ?",
        mobile: "« Et pour quoi faire ? » demande Guénolé. Personne ne bouge sur le pont.",
        preuve: "« Des mots, on en a eu assez depuis Port-Aubier, dit Rozenn. Montre-nous. »",
        none: "Rien que ta parole",
      },
    },
    C: { title: "De quoi souffre le capitaine ?", act: "II", solved: "c:verite",
      answer: { person: "morvan", text: "De la digitale. Morvan Le Hir en verse chaque soir dans le grog qu'il porte lui-même au capitaine." } },
    E: { title: "Qui a percé les tonneaux ?", act: "II", solved: "eau:coupable",
      answer: { person: "erwan", text: "Erwan Le Goff, avec la vrille volée à Armelle, sur l'ordre du second, à qui il devait de l'argent." } },
  },
  clues: {
    m_poids: { rev: "M", short: "Des caisses trop lourdes", text: "Les caisses marquées « draps de Flandre » pèsent autant que des caisses de clous. Les portefaix plient sous chacune." },
    m_lerac: { rev: "M", short: "Lerac a refusé de signer", text: "Thibaut Lerac, l'ancien subrécargue, a refusé de signer le manifeste sans ouvrir les caisses. Le lendemain matin, il est tombé dans l'escalier de l'entrepôt Corbière." },
    m_police: { rev: "M", short: "Une assurance énorme", text: "À la Chambre des Assurances, la Sterne et sa cargaison sont assurées pour quarante mille écus. Un trois-mâts de son âge en vaut à peine dix mille." },
    m_bergeronnette: { rev: "M", short: "Le rescapé de la Bergeronnette", text: "Sur la plaque des noyés de la chapelle de Gavre : la Bergeronnette, navire Corbière, perdue sur les Dents de Morgue il y a deux ans. Vingt-six noyés. Cinq rescapés, arrivés à Marbecq en chaloupe. Le premier nom de la liste des rescapés est « M. Le Hir, second »." },
    m_soizic: { rev: "M", short: "La chaloupe bien garnie", text: "La gardienne du phare de Ronce a vu passer la chaloupe des rescapés de la Bergeronnette. Elle avait de l'eau, du biscuit, une boussole, et des hommes qui ne ramaient pas comme des naufragés." },
    m_sable: { rev: "M", short: "Du sable dans les caisses", text: "Sous une couche de draps, les caisses de la cale sont pleines de sable et de galets de grève." },
    m_chaloupe: { rev: "M", short: "La chaloupe prête", text: "Sous la bâche de la chaloupe : deux barils d'eau, un sac de biscuit, une boussole, une voile roulée et le coffre de mer du second." },
    m_route: { rev: "M", short: "La route qui dérive", text: "Depuis Ronce, le second fait gouverner un quart plus au sud que la route portée sur la carte du capitaine. À ce train, la Sterne arrivera sur les Dents par la Mâchoire, loin de la Passe des Veuves." },
    m_lettre: { rev: "M", short: "La lettre de Corbière", text: "Dans le coffre du second, une lettre de Corbière : « Mille écus à votre retour, comme la dernière fois, quand la Chambre aura payé. Que le petit ne revienne pas. »" },
    m_pilote: { rev: "M", short: "Le pilote débarqué", text: "C'est le second qui a payé à boire au pilote Tréguer toute la nuit, à Gavre, puis qui a dit au capitaine que le pilote refusait de rembarquer." },
    c_digitale: { rev: "C", short: "La digitale du second", text: "Chez l'apothicaire Haudry, à Port-Aubier, le second de la Sterne a acheté une once de feuilles de digitale séchées, « pour le cœur de son capitaine »." },
    c_halos: { rev: "C", short: "Des halos jaunes", text: "Le capitaine Coët voit des halos jaunes autour des lanternes. Il a le pouls lent, des nausées, et il ne mange plus." },
    c_grog: { rev: "C", short: "Le grog du soir", text: "Chaque soir, c'est le second qui porte au capitaine son grog, préparé par Rozenn. Il le monte seul, par l'escalier de la dunette." },
    c_feuilles: { rev: "C", short: "Des feuilles au fond du pot", text: "Au fond du pot à grog du capitaine, une pâte verte de feuilles écrasées, amère au bout de la langue." },
    e_vrille: { rev: "E", short: "Des trous de vrille", text: "Les quatorze tonneaux ont été percés au ras du fond, d'un trou net de la taille d'un petit doigt : une vrille de charpentier." },
    e_armelle: { rev: "E", short: "La vrille d'Armelle", text: "La plus grosse vrille d'Armelle a disparu de son coffre à outils depuis Gavre.", leurre: true },
    e_sciure: { rev: "E", short: "La sciure mouillée", text: "Dans le hamac d'Erwan Le Goff, roulée dans une chemise, une vrille de charpentier encore collée de sciure de chêne humide." },
    e_dette: { rev: "E", short: "La dette d'Erwan", text: "Erwan Le Goff a perdu aux dés, à Port-Aubier, plus que sa solde de toute l'année. Il a dit à ses camarades qu'un homme du bord avait racheté sa dette." },
  },
